const TABS = ['basic', 'wheels', 'curves', 'hsl', 'match', 'lut', 'export', 'looks']

// ───────── 独立实现（不依赖页面） ─────────
function parseCubeT(text) {
  const lines = text.split(/\r?\n/), rows = []
  let N = 0, title = null
  for (const ln of lines) {
    const t = ln.replace(/#.*$/, '').trim()
    if (!t) continue
    if (/^TITLE\s/.test(t)) { title = t.replace(/^TITLE\s+"?|"$/g, ''); continue }
    if (/^LUT_3D_SIZE\s/.test(t)) { N = +t.split(/\s+/)[1]; continue }
    if (/^[A-Z_]/.test(t)) continue
    for (const v of t.split(/\s+/)) rows.push(+v)
  }
  return { N, title, rows }
}
function parse3dlT(text) {
  const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean)
  const head = []
  while (lines.length && !/^[\d\s.+-]+$/.test(lines[0])) head.push(lines.shift())   // 头部 = 含字母的行（Lustre 的 3DMESH / Mesh n b）
  const mesh = lines.shift().split(/\s+/).map(Number), N = mesh.length
  const ints = new Int32Array(N * N * N * 3)
  let k = 0
  for (let r = 0; r < N; r++) for (let g = 0; g < N; g++) for (let b = 0; b < N; b++) {
    const v = lines[k++].split(/\s+/).map(Number), di = ((b * N + g) * N + r) * 3
    ints[di] = v[0]; ints[di + 1] = v[1]; ints[di + 2] = v[2]
  }
  return { head, mesh, N, ints, dataLines: lines.length }
}
function pngDecode(buf) {
  const sig = [137, 80, 78, 71, 13, 10, 26, 10]
  for (let i = 0; i < 8; i++) if (buf[i] !== sig[i]) throw new Error('不是 PNG')
  let p = 8, w = 0, h = 0, ct = 0, bd = 0, idat = []
  while (p < buf.length) {
    const len = buf.readUInt32BE(p), type = buf.toString('latin1', p + 4, p + 8), data = buf.subarray(p + 8, p + 8 + len)
    const crc = buf.readUInt32BE(p + 8 + len)
    if (zlib.crc32(buf.subarray(p + 4, p + 8 + len)) !== crc) throw new Error('CRC 错误 ' + type)
    if (type === 'IHDR') { w = data.readUInt32BE(0); h = data.readUInt32BE(4); bd = data[8]; ct = data[9] }
    if (type === 'IDAT') idat.push(data)
    if (type === 'IEND') break
    p += 12 + len
  }
  if (bd !== 8 || (ct !== 6 && ct !== 2)) throw new Error(`不支持的 PNG：位深 ${bd} 色彩类型 ${ct}`)
  const bpp = ct === 6 ? 4 : 3, stride = w * bpp, raw = zlib.inflateSync(Buffer.concat(idat)), out = new Uint8Array(w * h * 4)
  let prev = new Uint8Array(stride), cur = new Uint8Array(stride)
  for (let y = 0; y < h; y++) {
    const f = raw[y * (stride + 1)], row = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1))
    for (let i = 0; i < stride; i++) {
      const a = i >= bpp ? cur[i - bpp] : 0, b = prev[i], c = i >= bpp ? prev[i - bpp] : 0
      let v = row[i]
      if (f === 1) v += a; else if (f === 2) v += b; else if (f === 3) v += (a + b) >> 1
      else if (f === 4) { const pp = a + b - c, pa = Math.abs(pp - a), pb = Math.abs(pp - b), pc = Math.abs(pp - c); v += pa <= pb && pa <= pc ? a : (pb <= pc ? b : c) }
      cur[i] = v & 255
    }
    for (let x = 0; x < w; x++) { const o = (y * w + x) * 4; out[o] = cur[x * bpp]; out[o + 1] = cur[x * bpp + 1]; out[o + 2] = cur[x * bpp + 2]; out[o + 3] = bpp === 4 ? cur[x * bpp + 3] : 255 }
    const t = prev; prev = cur; cur = t
  }
  return { w, h, data: out }
}
function pngEncode(w, h, rgba) {
  const raw = Buffer.alloc(h * (w * 4 + 1))
  for (let y = 0; y < h; y++) { raw[y * (w * 4 + 1)] = 0; Buffer.from(rgba.buffer, rgba.byteOffset + y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1) }
  const chunk = (type, data) => {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length)
    const td = Buffer.concat([Buffer.from(type, 'latin1'), data]), crc = Buffer.alloc(4); crc.writeUInt32BE(zlib.crc32(td))
    return Buffer.concat([len, td, crc])
  }
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))])
}
// 参考图（配色用）：与 gen_truth.py 的 refimg() 同一个整数公式
function refImage() {
  const w = 200, h = 120, px = new Uint8Array(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const o = (y * w + x) * 4
    px[o] = 200 + (x * 3 + y * 7) % 56 - Math.floor(y / 3)
    px[o + 1] = 60 + (x * 5 + y * 3) % 90 + Math.floor(y / 2)
    px[o + 2] = 90 + (x * 11 + y * 13) % 120 - Math.floor(x / 4)
    px[o + 3] = 255
  }
  return { w, h, data: px }
}

export default async ({ page, toolURL, screenshot, assert }) => {
  const waitFinal = () => page.waitForFunction(() => {
    const c = document.getElementById('lt-canvas'); return !!c && c.dataset.final === '1' && c.dataset.key === window.LT.stateKey()
  }, null, { timeout: 20000 })
  const onTab = async (t) => {
    await page.click(`#lt-tab-${t}`)
    await page.waitForFunction((t) => !document.getElementById('lt-pane-' + t).hidden && getComputedStyle(document.getElementById('lt-pane-' + t)).display !== 'none', t)
  }
  const press = async (sel, key, n = 1) => { await page.focus(sel); for (let i = 0; i < n; i++) await page.keyboard.press(key) }
  const dl = async (sel) => {
    const [d] = await Promise.all([page.waitForEvent('download', { timeout: 20000 }), page.click(sel)])
    return { name: d.suggestedFilename(), buf: fs.readFileSync(await d.path()) }
  }
  const status = () => page.textContent('#lt-status')
  const cmpLat = (rows, truth, tol, label) => {
    let worst = 0, at = -1
    // NaN 比较恒为假：`d > worst` 会让整张 NaN 的 LUT 悄悄过关，所以写成 !(d <= worst)
    ORACLE.latIdx.forEach((li, k) => { for (let c = 0; c < 3; c++) { const d = Math.abs(rows[li * 3 + c] - truth[k][c]); if (!(d <= worst)) { worst = Number.isNaN(d) ? Infinity : d; at = li } } })
    assert(worst <= tol, `${label}：网格最大偏差 ${worst.toExponential(3)} > ${tol}（节点 ${at}）`)
    return worst
  }
  const exportCube = async (label) => {
    await onTab('export')
    await page.click('#lt-exp-fmt [data-fmt="cube"]')
    const f = await dl('#lt-exp-download')
    const c = parseCubeT(f.buf.toString('utf8'))
    assert(c.N === 33 && c.rows.length === 33 ** 3 * 3, `${label}：.cube 应为 33³（${c.N}，${c.rows.length / 3} 行）`)
    return c
  }
  const readPix = (positions, w) => page.evaluate(([pos, w]) => {
    const c = document.getElementById('lt-canvas'), d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data, out = []
    for (const p of pos) { const x = p % w, y = Math.floor(p / w), i = (y * c.width + x) * 4; out.push(d[i], d[i + 1], d[i + 2]) }
    return out
  }, [positions, w])
  const resetAll = async () => { await onTab('basic'); await page.click('#lt-reset-all'); await waitFinal(); assert((await status()).startsWith('无调整'), '全部归零后应为恒等：' + await status()) }
  const setCompare = async (m) => { await page.click(`#lt-compare [data-mode="${m}"]`); await page.waitForFunction((m) => document.querySelector(`#lt-compare [data-mode="${m}"]`).getAttribute('aria-pressed') === 'true', m) }

  // ── 0 首屏 ──
  await page.goto(toolURL)
  await waitFinal()
  assert((await page.title()).includes('LUT'), '标题')
  assert(await page.$eval('a.lt-back', (a) => a.getAttribute('href') === '../../' && a.textContent.includes('← 返回工具集')), '返回链接')
  assert((await status()).startsWith('无调整'), '初始应为恒等：' + await status())
  assert(await page.$eval('#lt-canvas', (c) => c.width === 1200 && c.height === 706), '渔船预览 1200×706')
  // 恒等管线：调色后与原图逐像素相同
  await setCompare('after'); await waitFinal()
  const P706 = ORACLE.pix.map((p) => p % (1200 * 706))
  const idAfter = await readPix(P706, 1200)
  await setCompare('before'); await waitFinal()
  const idBefore = await readPix(P706, 1200)
  assert(idAfter.every((v, i) => v === idBefore[i]), '恒等参数：调色后像素应与原图完全相同')
  const boatsPix = idBefore

  // ── 1 色卡 + 示波器统计（真值：Python 直接数色卡像素） ──
  await page.click('#lt-samples [data-sample="chart"]'); await waitFinal()
  assert(await page.$eval('#lt-canvas', (c) => c.width === 1200 && c.height === 800), '色卡 1200×800')
  const I = ORACLE.I
  assert((await page.textContent('#lt-st-n')) === I.n.toLocaleString('en-US'), '像素数 ' + await page.textContent('#lt-st-n'))
  // 显示值按页面位数取整：比较容差 = 显示位数的半个最小单位（真值不在页面上取整，避免 0.035 这类边界的二进制表示差异）
  const near = async (sel, want, dp, label) => {
    const txt = await page.textContent(sel), v = parseFloat(txt)
    assert(Math.abs(v - want) <= 0.5 * 10 ** -dp + 1e-9, `${label} ${txt} vs ${want}`)
  }
  await near('#lt-st-clip-hi', I.clipHi, 2, '高光溢出')
  await near('#lt-st-clip-lo', I.clipLo, 2, '暗部死黑')
  await near('#lt-st-mean', I.meanY, 1, '平均亮度')
  assert((await page.textContent('#lt-st-median')) === String(I.median), `亮度中位 ${await page.textContent('#lt-st-median')} vs ${I.median}`)
  await near('#lt-st-sat', I.sat, 1, '平均饱和')
  const scopeMin = { hist: 5, wave: 5, parade: 8, vector: 7 }
  for (const sc of ['wave', 'parade', 'vector', 'hist']) {
    await page.click(`#lt-scope-tabs [data-scope="${sc}"]`)
    await page.waitForFunction((sc) => document.getElementById('lt-scope').dataset.mode === sc, sc)
    const r = await page.$eval('#lt-scope', (c) => {
      const x = c.getContext('2d'), d = x.getImageData(0, 0, c.width, c.height).data; let lit = 0
      for (let i = 0; i < d.length; i += 4) if (d[i] + d[i + 1] + d[i + 2] > 60) lit++
      return { labels: +c.dataset.labels, dropped: +c.dataset.dropped, lit }
    })
    assert(r.labels >= scopeMin[sc], `示波器 ${sc} 刻度文字只画了 ${r.labels} 个（应 ≥ ${scopeMin[sc]}，被避让丢 ${r.dropped}）`)
    assert(r.lit > 3000, `示波器 ${sc} 画布几乎是空的（亮像素 ${r.lit}）`)
  }

  // ── 2 ASC CDL（色轮面板直接输入数值）→ .cube / .3dl / Hald / .cdl ──
  await onTab('wheels')
  // 色轮方向键 → Slope：由 BT.709 的 Cb/Cr 定义推出的性质（与实现无关）：ΔR = 1.5748·Cr、ΔB = 1.8556·Cb、ΔG 让 Rec.709 亮度不变；增益色轮系数 0.5、每步 0.0035
  await press('#lt-puck-gain', 'ArrowUp', 10); await press('#lt-puck-gain', 'ArrowRight', 10)
  await waitFinal()
  const sl = [0, 1, 2].map(async (i) => +(await page.inputValue('#lt-cdl-s' + i)))
  const [s0, s1, s2] = await Promise.all(sl)
  const cr = 10 * 0.0035, cbv = 10 * 0.0035
  assert(Math.abs(s0 - (1 + 0.5 * 1.5748 * cr)) < 2e-6 && Math.abs(s2 - (1 + 0.5 * 1.8556 * cbv)) < 2e-6, `色轮 ↑→ 后 Slope R/B ${s0} ${s2}`)
  assert(Math.abs(0.2126 * (s0 - 1) + 0.7152 * (s1 - 1) + 0.0722 * (s2 - 1)) < 2e-6, `色轮偏移应保持 Rec.709 亮度不变：${s0} ${s1} ${s2}`)
  await page.focus('#lt-puck-gain'); await page.keyboard.press('Backspace'); await waitFinal()
  assert((await page.inputValue('#lt-cdl-s0')) === '1' && (await page.inputValue('#lt-cdl-s2')) === '1', 'Backspace 色轮归位')
  const A = ORACLE.A.cdl
  const fills = [['s', A.slope], ['o', A.offset], ['p', A.power]]
  for (const [f, v] of fills) for (let i = 0; i < 3; i++) { await page.fill(`#lt-cdl-${f}${i}`, String(v[i])); await page.press(`#lt-cdl-${f}${i}`, 'Tab') }
  await press('#lt-cdl-sat', 'ArrowRight', 15)
  await waitFinal()
  assert((await page.textContent('#lt-cdl-sat-v')) === A.sat.toFixed(2), 'CDL 饱和 ' + await page.textContent('#lt-cdl-sat-v'))
  const puckMoved = await page.$eval('#lt-puck-gain', (p) => p.style.left !== '50%' || p.style.top !== '50%')
  assert(puckMoved, '输入 Slope 后增益色轮的圆点应离开中心')
  // 非法输入：恢复原值、不改参数
  await page.fill('#lt-cdl-s0', 'abc'); await page.press('#lt-cdl-s0', 'Tab')
  assert((await page.inputValue('#lt-cdl-s0')) === '1.15', '非法输入应恢复原值：' + await page.inputValue('#lt-cdl-s0'))
  await onTab('export')
  await page.fill('#lt-exp-title', 'Test CDL')
  const cA = await exportCube('CDL')
  assert(cA.title === 'Test CDL', '.cube TITLE 应为输入的标题：' + cA.title)
  const wA = cmpLat(cA.rows, ORACLE.A.lat, 1e-6, 'CDL .cube 对 OCIO 核过的 ASC CDL')
  // .3dl Flame：蓝最快、10 位网格、12 位整数
  await page.click('#lt-exp-fmt [data-fmt="3dl-flame"]')
  const f3 = await dl('#lt-exp-download')
  assert(f3.name.endsWith('.3dl'), '.3dl 文件名 ' + f3.name)
  const d3 = parse3dlT(f3.buf.toString('utf8'))
  assert(d3.N === 33 && d3.mesh[0] === 0 && d3.mesh[32] === 1023 && d3.mesh[1] === 32 && d3.head.length === 0, `.3dl 网格行 ${d3.mesh.slice(0, 3)}…${d3.mesh[32]}`)
  let q12 = 0
  ORACLE.latIdx.forEach((li, k) => { for (let c = 0; c < 3; c++) q12 = Math.max(q12, Math.abs(d3.ints[li * 3 + c] - ORACLE.A.q12[k][c])) })
  assert(q12 <= 1, `.3dl 12 位整数与真值最多差 ${q12}`)
  await page.click('#lt-exp-fmt [data-fmt="3dl-lustre"]')
  const fl = await dl('#lt-exp-download')
  const dlu = parse3dlT(fl.buf.toString('utf8'))
  assert(dlu.head[0] === '3DMESH' && dlu.head[1] === 'Mesh 5 12', 'Lustre 头 ' + dlu.head.join(' | '))
  // Hald：33 → 等级 6（36³，216×216）
  await page.click('#lt-exp-fmt [data-fmt="hald"]')
  const fh = await dl('#lt-exp-download')
  const ph = pngDecode(fh.buf)
  assert(ph.w === 216 && ph.h === 216, `Hald 应为 216×216，实得 ${ph.w}×${ph.h}`)
  let hd = 0
  ORACLE.A.h36idx.forEach((li, k) => { for (let c = 0; c < 3; c++) hd = Math.max(hd, Math.abs(ph.data[li * 4 + c] - ORACLE.A.h36[k][c])) })
  assert(hd <= 1, `Hald 节点与真值最多差 ${hd} 个码值`)
  await page.click('#lt-exp-fmt [data-fmt="cube"]')
  // .cdl 下载：数值与输入一致
  await onTab('wheels')
  const fc = await dl('#lt-cdl-save')
  const xml = fc.buf.toString('utf8'), tri = (tag) => xml.match(new RegExp(`<${tag}>([^<]*)</${tag}>`))[1].trim().split(/\s+/).map(Number)
  assert(JSON.stringify(tri('Slope')) === JSON.stringify(A.slope) && JSON.stringify(tri('Offset')) === JSON.stringify(A.offset) && JSON.stringify(tri('Power')) === JSON.stringify(A.power), '.cdl 数值 ' + xml.slice(0, 300))
  assert(Number(xml.match(/<Saturation>([^<]*)</)[1]) === A.sat && /urn:ASC:CDL:v1\.01/.test(xml), '.cdl 饱和 / 命名空间')
  // 精度自检：33³ 四面体插值 vs 逐点直算
  await onTab('export')
  await page.waitForFunction(() => document.getElementById('lt-exp-acc').dataset.n === '33')
  // 异源核对：同一组 mulberry32 随机色，Python 用 colour 的四面体插值算出的最大 / 99% 分位误差（CDL 的截断拐点与 x^0.95 让误差在 1e-2 量级，是 LUT 本身的误差）
  const acc = await page.$eval('#lt-exp-acc', (d) => ({ max: +d.dataset.max, p99: +d.dataset.p99 }))
  assert(Math.abs(acc.max - ORACLE.A.acc.max) < 1e-9 && Math.abs(acc.p99 - ORACLE.A.acc.p99) < 1e-9, `精度自检 ${acc.max} / ${acc.p99} vs colour ${ORACLE.A.acc.max} / ${ORACLE.A.acc.p99}`)

  // ── 3 曲线（scipy PCHIP） ──
  await resetAll()
  await onTab('curves')
  await page.click('[data-curve-preset="s"]')
  await page.click('#lt-curve-ch [data-ch="r"]')
  await page.focus('#lt-curve-svg'); await page.keyboard.press('Enter')
  await page.waitForFunction(() => document.getElementById('lt-curve-svg').dataset.points === '3')
  await page.keyboard.press('Shift+ArrowUp'); await page.keyboard.press('Shift+ArrowUp'); await page.keyboard.press('ArrowRight')
  await waitFinal()
  const lab = await page.$eval('#lt-curve-svg .lt-cpt[data-i="1"]', (g) => g.getAttribute('aria-label'))
  const rx = Math.round(ORACLE.B.red[0][1] * 255), ry = Math.round(ORACLE.B.red[1][1] * 255)   // 真值脚本按「Enter 加点 + Shift↑×2 + →」逐步四位小数取整复算
  assert(lab.includes(`输入 ${rx}，`) && lab.includes(`输出 ${ry}`), `红通道中点 ${lab}（应为 ${rx} → ${ry}）`)
  const cB = await exportCube('曲线')
  const wB = cmpLat(cB.rows, ORACLE.B.lat, 1e-6, '曲线 .cube 对 scipy PchipInterpolator')
  // 加点 / 双击删点 / 端点不可删
  await onTab('curves')
  await page.click('#lt-curve-ch [data-ch="g"]')
  const box = await page.$eval('#lt-curve-svg', (s) => { s.scrollIntoView({ block: 'center' }); const r = s.getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height } })
  const at = (u, v) => ({ x: box.x + (u * 256 + 8) / 272 * box.w, y: box.y + ((1 - v) * 256 + 8) / 272 * box.h })
  const p1 = at(0.3, 0.45)
  await page.mouse.click(p1.x, p1.y)
  await page.waitForFunction(() => document.getElementById('lt-curve-svg').dataset.points === '3')
  await page.mouse.dblclick(p1.x, p1.y)
  await page.waitForFunction(() => document.getElementById('lt-curve-svg').dataset.points === '2')
  await page.focus('#lt-curve-svg .lt-cpt[data-i="0"]'); await page.keyboard.press('Delete')
  await page.waitForFunction(() => !document.getElementById('lt-toast').hidden && document.getElementById('lt-toast').textContent.includes('端点'))
  assert((await page.$eval('#lt-curve-svg', (s) => s.dataset.points)) === '2', '端点删不掉')

  // ── 3b 导入风格 JSON（精确控制点）：触发 PCHIP 端点形状保护的两个分支，对 scipy 逐点比
  await resetAll()
  await onTab('looks')
  const lookJson = JSON.stringify({ format: 'lut-studio-looks', version: 1, looks: [{ name: '端点分支', params: { curves: { master: ORACLE.B2.master, r: ORACLE.B2.red } } }] })
  await page.setInputFiles('#lt-looks-file', { name: 'looks.json', mimeType: 'application/json', buffer: Buffer.from(lookJson) })
  await page.waitForFunction(() => document.querySelectorAll('#lt-mylooks li').length === 1)
  await page.click('#lt-mylooks li [data-act="apply"]'); await waitFinal()
  const cB2 = await exportCube('端点分支曲线')
  const wB2 = cmpLat(cB2.rows, ORACLE.B2.lat, 1e-6, '端点形状保护曲线 .cube 对 scipy PchipInterpolator')
  await onTab('looks'); await page.click('#lt-mylooks li [data-act="del"]')
  await page.waitForFunction(() => document.querySelectorAll('#lt-mylooks li').length === 0)

  // ── 4 曝光 + 色温（colour-science） ──
  await resetAll()
  await press('#lt-temp', 'ArrowRight', 40)
  await press('#lt-exposure', 'ArrowRight', 50)
  await waitFinal()
  assert((await page.textContent('#lt-temp-v')) === '+40' && (await page.textContent('#lt-exposure-v')) === '+0.50', '滑块读数')
  assert((await page.textContent('#lt-wb-read')).includes(Math.round(ORACLE.C.cct) + ' K'), '白点读数 ' + await page.textContent('#lt-wb-read'))
  const cC = await exportCube('白平衡')
  const wC = cmpLat(cC.rows, ORACLE.C.lat, 1e-6, '曝光 + 色温 .cube 对 colour-science')

  // ── 4b 整体强度：强度 50% = 输入与「100% 时显示的值」的中点（饱和度 +100 让大量节点在 100% 时被截断，未截断就混合会偏）
  await resetAll()
  await press('#lt-saturation', 'End')
  await waitFinal()
  const c100 = await exportCube('饱和度 +100')
  await onTab('basic'); await press('#lt-strength', 'PageDown', 5); await waitFinal()
  assert((await page.textContent('#lt-strength-v')) === '50', '强度 ' + await page.textContent('#lt-strength-v'))
  const c50 = await exportCube('强度 50%')
  let lin = 0, clipped = 0
  for (let i = 0; i < 33 ** 3; i++) {
    const x = [i % 33, Math.floor(i / 33) % 33, Math.floor(i / 1089)].map((v) => v / 32)
    for (let c = 0; c < 3; c++) { lin = Math.max(lin, Math.abs(c50.rows[i * 3 + c] - (x[c] + 0.5 * (c100.rows[i * 3 + c] - x[c])))); if (c100.rows[i * 3 + c] === 0 || c100.rows[i * 3 + c] === 1) clipped++ }
  }
  assert(clipped > 5000, '语料里应有大量在 100% 时被截断的分量：' + clipped)
  assert(lin <= 1.5e-6, `强度 50% 应是输入与 100% 显示值的中点：最大偏差 ${lin}`)

  // ── 5 HSL 红色饱和度 −100（OKLab；性质：纯红变成同 OKLab 明度的灰、纯蓝不动） ──
  await resetAll()
  await onTab('hsl')
  await page.click('#lt-hsl-prop [data-prop="sat"]')
  await press('#lt-hsl-0', 'Home')
  await waitFinal()
  assert((await page.textContent('#lt-hsl-0-v')) === '-100', 'HSL 红 ' + await page.textContent('#lt-hsl-0-v'))
  const cD = await exportCube('HSL')
  const wD = cmpLat(cD.rows, ORACLE.D.lat, 1e-6, 'HSL .cube 对 OKLab 转写')
  const red = 32 * 3, blue = 32 * 33 * 33 * 3
  assert(Math.abs(cD.rows[red] - ORACLE.D.redToGray) < 1e-6 && Math.abs(cD.rows[red + 1] - ORACLE.D.redToGray) < 1e-6 && Math.abs(cD.rows[red + 2] - ORACLE.D.redToGray) < 1e-6,
    `纯红应变成 OKLab 同明度的灰 ${ORACLE.D.redToGray}：${cD.rows.slice(red, red + 3)}`)
  assert(Math.abs(cD.rows[blue]) < 1e-6 && Math.abs(cD.rows[blue + 1]) < 1e-6 && Math.abs(cD.rows[blue + 2] - 1) < 1e-6, '纯蓝不受红色分区影响：' + cD.rows.slice(blue, blue + 3))

  // ── 6 S-Log3 灰片（colour 的 S-Log3 + S-Gamut3.Cine） ──
  await resetAll()
  await page.click('#lt-samples [data-sample="slog3"]'); await waitFinal()
  assert((await page.inputValue('#lt-input')) === 'slog3', '选 S-Log3 灰片后输入色彩空间应自动切到 S-Log3')
  assert((await page.textContent('#lt-toast')).includes('S-Log3'), '应提示已切换输入色彩空间')
  const cE = await exportCube('S-Log3')
  const wE = cmpLat(cE.rows, ORACLE.E.lat, 1e-6, 'S-Log3 输入变换 .cube 对 colour-science')
  await setCompare('after'); await waitFinal()
  const restored = await readPix(P706, 1200)
  let rMax = 0, rSum = 0
  restored.forEach((v, i) => { const d = Math.abs(v - boatsPix[i]); rSum += d; if (d > rMax) rMax = d })
  // 8 位 Log 灰片的量化误差（对拍台 s12：不经 LUT 时照片 4–13 个码值）+ 33³ 插值：只做往返健全性检查，精确数学由上面的网格对拍兜住
  assert(rMax <= 16 && rSum / restored.length < 1.2, `灰片还原后应接近原图：最大差 ${rMax}、平均 ${(rSum / restored.length).toFixed(3)}`)
  await setCompare('split')
  await page.click('#lt-samples [data-sample="chart"]'); await waitFinal()
  assert((await page.inputValue('#lt-input')) === 'srgb', '离开灰片后输入色彩空间应自动改回 sRGB')

  // ── 7 配色（color-matcher） ──
  const ref = refImage()
  let refSum = 0; for (let i = 0; i < ref.data.length; i++) if (i % 4 !== 3) refSum += ref.data[i]
  assert(refSum === ORACLE.F.refSum, `参考图公式与 Python 不一致 ${refSum} vs ${ORACLE.F.refSum}`)
  await onTab('match')
  await page.setInputFiles('#lt-ref-file', { name: 'ref.png', mimeType: 'image/png', buffer: pngEncode(ref.w, ref.h, ref.data) })
  await page.waitForFunction(() => document.getElementById('lt-ref-info').textContent.startsWith('ref.png'))
  await page.click('#lt-match-method [data-method="mkl"]'); await waitFinal()
  await page.waitForFunction(() => document.getElementById('lt-match-stats').dataset.method === 'mkl')
  const tRow = await page.$$eval('#lt-match-stats dd', (dd) => dd.slice(0, 3).map((d) => d.textContent))
  const T = ORACLE.F.mkl.T
  for (let r = 0; r < 3; r++) assert(tRow[r] === T.slice(r * 3, r * 3 + 3).map((v) => v.toFixed(4)).join(' '), `MKL 传输矩阵第 ${r + 1} 行 ${tRow[r]}`)
  const cF1 = await exportCube('MKL')
  const wF1 = cmpLat(cF1.rows, ORACLE.F.mkl.lat, 1e-6, 'MKL .cube 对 color-matcher')
  await onTab('match'); await page.click('#lt-match-method [data-method="reinhard"]'); await waitFinal()
  const cF2 = await exportCube('Reinhard')
  const wF2 = cmpLat(cF2.rows, ORACLE.F.reinhard.lat, 1e-6, 'Reinhard .cube 对 color-matcher')
  await setCompare('after'); await waitFinal()
  const rhPix = await readPix(ORACLE.pix, 1200)
  let rhMax = 0, rhSum = 0, rhLut = 0
  ORACLE.F.reinhard.pix.forEach((t, k) => { for (let c = 0; c < 3; c++) { const d = Math.abs(rhPix[k * 3 + c] - t[c]); rhSum += d; if (d > rhMax) rhMax = d; if (rhPix[k * 3 + c] === ORACLE.F.reinhard.pixLut[k][c]) rhLut++ } })
  // 精确模型：color-matcher 的变换 → 烘 33³ → colour 的四面体插值 → 四舍五入，页面应逐值一致
  assert(rhLut === rhPix.length, `Reinhard 预览对「color-matcher 变换 + 33³ 四面体插值」逐值一致 ${rhLut}/${rhPix.length}`)
  // 与逐像素直算的差就是 33³ 插值误差：Reinhard 在暗部取 log10，第一格最陡
  assert(rhMax <= 6 && rhSum / rhPix.length < 0.2, `Reinhard 预览对 color-matcher 整图直算：最大差 ${rhMax}、平均 ${(rhSum / rhPix.length).toFixed(3)}`)
  await setCompare('split')
  await onTab('match'); await page.click('#lt-match-method [data-method="hm"]'); await waitFinal()
  const cF3 = await exportCube('直方图')
  const wF3 = cmpLat(cF3.rows, ORACLE.F.hm.lat, 1e-6, '直方图匹配 .cube 对 color-matcher')
  await onTab('match'); await page.click('#lt-match-method [data-method="none"]'); await waitFinal()
  assert((await status()).startsWith('无调整'), '配色关掉后回到恒等')

  // ── 8 导入 LUT：.cube（ffmpeg lut3d 实跑）、Flame .3dl（OCIO）、坏文件、Hald 滤镜工作流 ──
  await onTab('lut')
  await page.setInputFiles('#lt-lut-file', { name: 'g1.cube', mimeType: 'text/plain', buffer: Buffer.from(ORACLE.G1.cube) })
  await page.waitForFunction(() => document.getElementById('lt-lut-report').dataset.state === 'ok')
  await waitFinal()
  assert((await page.textContent('#lt-lut-size')) === '9³', '导入网格 ' + await page.textContent('#lt-lut-size'))
  assert(await page.$eval('#lt-lut-cube', (c) => c.dataset.points === '729'), '立方体视图应画 729 个节点')
  assert(await page.$$eval('#lt-lut-neutral path', (p) => p.length === 3), '中性轴应有三条曲线')
  await setCompare('after'); await waitFinal()
  const g1 = await readPix(ORACLE.pix, 1200)
  let ffMax = 0, flExact = 0
  ORACLE.G1.ffmpeg.forEach((t, k) => { for (let c = 0; c < 3; c++) { ffMax = Math.max(ffMax, Math.abs(g1[k * 3 + c] - t[c])); if (g1[k * 3 + c] === ORACLE.G1.float8[k][c]) flExact++ } })
  assert(ffMax <= 1, `导入 .cube 的预览对 ffmpeg lut3d 最多差 ${ffMax}`)
  assert(flExact === ORACLE.G1.float8.length * 3, `导入 .cube 的预览对 colour 四面体插值（四舍五入）应逐值相同：${flExact}/${ORACLE.G1.float8.length * 3}`)
  await page.click('#lt-lut-interp [data-interp="trilinear"]'); await waitFinal()
  const g1t = await readPix(ORACLE.pix, 1200)
  assert(g1t.some((v, i) => v !== g1[i]), '换成三线性插值后预览应有变化')
  await page.click('#lt-lut-interp [data-interp="tetrahedral"]'); await waitFinal()
  // 另存为 .cube：与导入的文件逐值一致（round-trip）
  const fcv = await dl('[data-conv="cube"]')
  const back = parseCubeT(fcv.buf.toString('utf8')), orig = parseCubeT(ORACLE.G1.cube)
  assert(back.N === 9 && back.rows.every((v, i) => Math.abs(v - orig.rows[i]) < 1e-6), '另存为 .cube 应与导入的文件逐值一致')
  // Flame .3dl（OCIO 烘）
  const t3 = zlib.gunzipSync(Buffer.from(ORACLE.G2.gz, 'base64'))
  await page.setInputFiles('#lt-lut-file', { name: 'ocio-flame.3dl', mimeType: 'text/plain', buffer: t3 })
  await page.waitForFunction(() => document.getElementById('lt-lut-info').textContent.includes('ocio-flame.3dl'))
  await waitFinal()
  assert((await page.textContent('#lt-lut-info')).includes('12 位输出'), '.3dl 输出位深应识别为 12 位')
  const g2 = await readPix(ORACLE.pix, 1200)
  let g2Max = 0
  ORACLE.G2.pix.forEach((t, k) => { for (let c = 0; c < 3; c++) g2Max = Math.max(g2Max, Math.abs(g2[k * 3 + c] - t[c])) })
  assert(g2Max <= 1, `Flame .3dl 预览对 OCIO 套用同一文件最多差 ${g2Max}`)
  // 坏文件：报错、不替换当前 LUT
  const bad = ORACLE.G1.cube.split('\n').slice(0, -11).join('\n') + '\n'
  await page.setInputFiles('#lt-lut-file', { name: 'broken.cube', mimeType: 'text/plain', buffer: Buffer.from(bad) })
  await page.waitForFunction(() => document.getElementById('lt-lut-report').dataset.state === 'error')
  const rep = await page.textContent('#lt-lut-report')
  assert(rep.includes('数据行数不对') && rep.includes('ocio-flame.3dl'), '坏文件报告：' + rep.slice(0, 200))
  assert((await page.textContent('#lt-lut-info')).includes('ocio-flame.3dl'), '坏文件不应替换当前 LUT')
  const nanCube = ORACLE.G1.cube.replace(/\n([0-9.]+) ([0-9.]+) ([0-9.]+)\n/, '\nnan $2 $3\n')
  await page.setInputFiles('#lt-lut-file', { name: 'nan.cube', mimeType: 'text/plain', buffer: Buffer.from(nanCube) })
  await page.waitForFunction(() => document.getElementById('lt-lut-report').textContent.includes('nan.cube'))
  const rep2 = await page.textContent('#lt-lut-report')
  assert(/第 3 行有非数字/.test(rep2) && !rep2.includes('行数不对'), 'nan 行应报具体行号：' + rep2.slice(0, 160))
  // Hald：下载恒等图 → 独立解码核对 → 测试里施加一个已知变换 → 拖回当 LUT
  const fid = await dl('[data-hald-level="8"]')
  const hid = pngDecode(fid.buf)
  assert(hid.w === 512 && hid.h === 512, '恒等 Hald 8 应为 512×512')
  let idBad = 0
  for (let i = 0; i < 64 ** 3; i++) {
    const r = i % 64, g = Math.floor(i / 64) % 64, b = Math.floor(i / 4096)
    if (hid.data[i * 4] !== Math.round(r * 255 / 63) || hid.data[i * 4 + 1] !== Math.round(g * 255 / 63) || hid.data[i * 4 + 2] !== Math.round(b * 255 / 63)) idBad++
  }
  assert(idBad === 0, `恒等 Hald 有 ${idBad} 个像素不对`)
  const Tf = (r, g, b) => [255 - r, g, Math.round(0.5 * b + 64)]
  const hx = new Uint8Array(hid.data)
  for (let i = 0; i < hx.length; i += 4) { const t = Tf(hx[i], hx[i + 1], hx[i + 2]); hx[i] = t[0]; hx[i + 1] = t[1]; hx[i + 2] = t[2] }
  await page.setInputFiles('#lt-lut-file', { name: 'filtered-hald.png', mimeType: 'image/png', buffer: pngEncode(512, 512, hx) })
  await page.waitForFunction(() => document.getElementById('lt-lut-info').textContent.includes('filtered-hald.png'))
  await waitFinal()
  assert((await page.textContent('#lt-lut-size')) === '64³', 'Hald 8 → 64³')
  await setCompare('before'); await waitFinal()
  const chartPix = await readPix(ORACLE.pix, 1200)
  await setCompare('after'); await waitFinal()
  const hp = await readPix(ORACLE.pix, 1200)
  let hMax = 0
  for (let k = 0; k < ORACLE.pix.length; k++) { const t = Tf(chartPix[k * 3], chartPix[k * 3 + 1], chartPix[k * 3 + 2]); for (let c = 0; c < 3; c++) hMax = Math.max(hMax, Math.abs(hp[k * 3 + c] - t[c])) }
  assert(hMax <= 1, `Hald 滤镜 LUT 的预览与已知变换最多差 ${hMax}`)
  // LUT 强度 50%：结果落在原图与 LUT 之间
  await press('#lt-lut-strength', 'PageDown', 5)
  await waitFinal()
  assert((await page.textContent('#lt-lut-strength-v')) === '50', 'LUT 强度 ' + await page.textContent('#lt-lut-strength-v'))
  const half = await readPix(ORACLE.pix, 1200)
  let midBad = 0
  for (let k = 0; k < ORACLE.pix.length * 3; k++) { const want = (chartPix[k] + hp[k]) / 2; if (Math.abs(half[k] - want) > 1.01) midBad++ }
  assert(midBad === 0, `LUT 强度 50% 时有 ${midBad} 个分量不在原图与满强度的中点 ±1`)
  await page.click('#lt-lut-remove'); await waitFinal()
  assert((await status()).startsWith('无调整'), '移除 LUT 后回到恒等')
  await setCompare('split')

  // ── 9 风格库 + localStorage（含 pagehide 补写） ──
  await page.click('#lt-samples [data-sample="boats"]'); await waitFinal()
  await onTab('looks')
  await page.click('.lt-look[data-look="teal-orange"]'); await waitFinal()
  assert(await page.$eval('.lt-look[data-look="teal-orange"]', (b) => b.getAttribute('aria-pressed') === 'true'), '当前风格卡应标记为按下')
  assert(/^4 个处理步骤/.test(await status()), '青橙 = 对比度 + 高光 + CDL + HSL 四步：' + await status())
  await page.fill('#lt-look-name', 'Test Look'); await page.click('#lt-look-save')
  await page.waitForFunction(() => document.querySelectorAll('#lt-mylooks li').length === 1)
  await page.reload(); await waitFinal()
  await onTab('looks')
  assert((await page.$$eval('#lt-mylooks li span', (s) => s.map((x) => x.textContent))).join() === 'Test Look', '刷新后「我的风格」应还在')
  assert(await page.$eval('.lt-look[data-look="teal-orange"]', (b) => b.getAttribute('aria-pressed') === 'true'), '刷新后调色参数也应恢复')
  await page.click('#lt-mylooks li [data-act="del"]')
  await page.reload(); await waitFinal()
  await onTab('looks')
  assert((await page.$$eval('#lt-mylooks li', (l) => l.length)) === 0, '删除后刷新应为空')
  await resetAll()
  await press('#lt-contrast', 'ArrowRight', 5)
  await page.reload(); await waitFinal()
  assert((await page.inputValue('#lt-contrast')) === '5', '改完滑块立刻刷新，参数应已保存（pagehide 补写）：' + await page.inputValue('#lt-contrast'))

  // ── 9b localStorage 被写坏：原型链键 / 非数字 / 坏曲线 / 越界一律回落默认，页面照常渲染
  // 先离开工具页（它的 pagehide 补写会落盘），在同源首页写坏存档，再回来
  const key = await page.evaluate(() => window.LT.storeKey)
  await page.goto(new URL('../../', toolURL).href)
  await page.evaluate((k) => localStorage.setItem(k, JSON.stringify({ v: 1, params: { input: 'toString', exposure: 'abc', tone: { contrast: 999 }, curves: { master: [[0.5, 'x']] }, cdl: { power: [0, -1, 'y'] } }, ui: { tab: 'constructor', sample: '__proto__' }, looks: [null, { name: 7 }] })), key)
  await page.goto(toolURL); await waitFinal()
  assert((await page.inputValue('#lt-input')) === 'srgb' && (await page.inputValue('#lt-contrast')) === '100' && (await page.inputValue('#lt-exposure')) === '0', '坏存档：input 回落 sRGB、对比度夹到 100、曝光回默认')
  assert(await page.$eval('#lt-tab-basic', (b) => b.getAttribute('aria-selected') === 'true'), '坏存档：面板回落「基础」')
  await resetAll()
  await press('#lt-contrast', 'ArrowRight', 5)
  await page.reload(); await waitFinal()

  // ── 10 ⌘K 命令面板 + 撤销 / 重做 ──
  await page.keyboard.press('Control+k')
  await page.waitForFunction(() => !document.getElementById('lt-cmdk').hidden)
  await page.keyboard.type('漂白')
  await page.waitForFunction(() => document.getElementById('lt-cmdk-list').dataset.count === '1')
  await page.keyboard.press('Enter')
  await waitFinal()
  assert(await page.$eval('#lt-cmdk', (m) => getComputedStyle(m).display === 'none'), '执行后命令面板应关闭')
  assert((await page.inputValue('#lt-contrast')) === '45' && (await page.inputValue('#lt-saturation')) === '-45', '命令面板套用「漂白」')
  await page.click('#lt-undo'); await waitFinal()
  assert((await page.inputValue('#lt-contrast')) === '5', '撤销应回到对比度 5：' + await page.inputValue('#lt-contrast'))
  await page.click('#lt-redo'); await waitFinal()
  assert((await page.inputValue('#lt-contrast')) === '45', '重做应回到 45')
  await page.keyboard.press('Control+k'); await page.keyboard.type('没有这个命令zzz')
  await page.waitForFunction(() => document.getElementById('lt-cmdk-list').dataset.count === '0')
  await page.keyboard.press('Escape')
  await page.waitForFunction(() => document.getElementById('lt-cmdk').hidden)

  // ── 11 分屏把手（键盘）+ 像素读数 ──
  await page.focus('#lt-split'); await page.keyboard.press('ArrowLeft')
  assert((await page.getAttribute('#lt-split', 'aria-valuenow')) === '48', '分屏把手 ← 应到 48%')
  await page.keyboard.press('ArrowRight')
  const cb = await page.$eval('#lt-canvas', (c) => { const r = c.getBoundingClientRect(); return { x: r.left + r.width * 0.75, y: r.top + r.height * 0.5 } })
  await page.mouse.move(cb.x, cb.y)
  await page.waitForFunction(() => document.getElementById('lt-pxread').textContent.includes('→'))

  // ── 12 导出全尺寸 PNG：独立解码，尺寸与像素对得上预览 ──
  await onTab('export')
  await page.click('#lt-img-fmt [data-img="png"]')
  const fimg = await dl('#lt-img-download')
  const pimg = pngDecode(fimg.buf)
  assert(pimg.w === 1200 && pimg.h === 706, `导出图片尺寸 ${pimg.w}×${pimg.h}`)
  await setCompare('after'); await waitFinal()
  const prevPix = await readPix(P706, 1200)
  let eMax = 0
  P706.forEach((p, k) => { for (let c = 0; c < 3; c++) eMax = Math.max(eMax, Math.abs(pimg.data[p * 4 + c] - prevPix[k * 3 + c])) })
  assert(eMax <= 2, `导出图片（65³）与预览（33³）最多差 ${eMax}`)
  await setCompare('split')

  // ── 13 渲染守卫（逐页签 × 逐视口） ──
  await onTab('lut')
  await page.setInputFiles('#lt-lut-file', { name: 'g1.cube', mimeType: 'text/plain', buffer: Buffer.from(ORACLE.G1.cube) })
  await page.waitForFunction(() => document.getElementById('lt-lut-report').dataset.state === 'ok')
  await waitFinal()
  const nCtl = await renderGuards(page, {
    assert, tabs: TABS, onTab,
    paneSel: (t) => `#lt-pane-${t}`, panesRoot: '#lt-panes',
    figSel: (t) => `#lt-pane-${t} svg#lt-lut-neutral`, cardSel: '.lt-card',
    minControls: 60, minTextsInFig: 0,
  })
  await onTab('lut')
  const nt = await page.$$eval('#lt-lut-neutral text', (t) => t.length)
  assert(nt === 6, '中性轴刻度文字应为 6 个：' + nt)
  await guardBoxOverlap(page, { assert, sel: '#lt-tabs .lt-tab, #lt-samples .lt-pill, #lt-compare .lt-pill, #lt-scope-tabs .lt-pill, #lt-scope-src .lt-pill, .lt-hero-meta .lt-badge, #lt-exp-fmt .lt-pill' })
  await page.click('#lt-lut-remove'); await waitFinal()

  // ── 缩略图：渔船 + 青橙，分屏 ──
  await onTab('looks')
  await page.click('.lt-look[data-look="teal-orange"]'); await waitFinal()
  await onTab('wheels')
  await page.click('#lt-scope-tabs [data-scope="vector"]')
  await page.evaluate(() => window.scrollTo(0, document.querySelector('.lt-main').offsetTop - 56))
  await page.waitForFunction(() => document.getElementById('lt-toast').hidden, null, { timeout: 6000 })   // 提示条消失后再截图
  console.log(`    偏差：CDL ${wA.toExponential(1)} 曲线 ${wB.toExponential(1)} 白平衡 ${wC.toExponential(1)} HSL ${wD.toExponential(1)} S-Log3 ${wE.toExponential(1)} MKL ${wF1.toExponential(1)} Reinhard ${wF2.toExponential(1)} 直方图 ${wF3.toExponential(1)}；灰片还原 ${rMax}/${(rSum / restored.length).toFixed(2)}；Reinhard 预览 ${rhMax}/${(rhSum / rhPix.length).toFixed(2)}；ffmpeg ${ffMax}；控件 ${nCtl}`)
  await screenshot('thumb.png')
}
